<script setup lang="ts">
import { computed, ref } from 'vue';
import { router, useForm, usePage } from '@inertiajs/vue3';
import AppLayout from '../../Layouts/AppLayout.vue';
import { CalendarDays, CheckCircle2, ChevronDown, Clock3, Dumbbell, Plus, Target, Trash2, UsersRound, X } from '@lucide/vue';
type Team={id:number;name:string}; type Athlete={id:number;name:string;team_ids:number[]};
type Exercise={id:number;day_label:string|null;title:string;category:string;sets:number|null;reps:number|null;duration_minutes:number|null;rest_seconds:number|null;notes:string|null;completion_count:number};
type Plan={id:number;title:string;description:string|null;status:string;starts_on:string;ends_on:string;coach:string;target:string|null;target_type:string;exercises:Exercise[]};
const props=defineProps<{plans:Plan[];teams:Team[];athletes:Athlete[]}>(); const page=usePage();
const showForm=ref(false); const openPlan=ref<number|null>(props.plans[0]?.id||null);
const emptyExercise=()=>({day_label:'روز اول',title:'',category:'jump',sets:null as number|null,reps:null as number|null,duration_minutes:null as number|null,rest_seconds:null as number|null,notes:''});
const form=useForm({title:'',description:'',target_type:'team',team_id:props.teams[0]?.id||null as number|null,athlete_id:null as number|null,starts_on:new Date().toISOString().slice(0,10),ends_on:'',status:'active',exercises:[emptyExercise()]});
const categories={strength:'قدرتی',jump:'پرش',speed:'سرعت و چابکی',serve:'سرویس',reception:'دریافت',spike:'اسپک',block:'دفاع روی تور',recovery:'ریکاوری'};
const athletes=computed(()=>form.target_type==='team'&&form.team_id?props.athletes.filter(a=>a.team_ids.includes(Number(form.team_id))):props.athletes);
const addExercise=()=>form.exercises.push(emptyExercise()); const removeExercise=(index:number)=>{if(form.exercises.length>1)form.exercises.splice(index,1);};
const submit=()=>form.post('/training-plans',{preserveScroll:true,onSuccess:()=>{showForm.value=false;form.reset();form.exercises=[emptyExercise()];}});
const setStatus=(plan:Plan,status:string)=>router.patch(`/training-plans/${plan.id}/status`,{status},{preserveScroll:true});
const statusLabel=(value:string)=>({draft:'پیش‌نویس',active:'فعال',completed:'تکمیل‌شده'}[value]||value);
const dateLabel=(value:string)=>new Intl.DateTimeFormat('fa-IR',{day:'numeric',month:'short'}).format(new Date(`${value}T12:00:00`));
</script>
<template><AppLayout title="برنامه‌های تمرینی" eyebrow="طراحی مسیر رشد ورزشکار" active="coach">
<div v-if="page.props.flash?.success" class="mb-4 flex items-center gap-2 rounded-xl bg-emerald-50 p-3 text-xs font-bold text-emerald-700"><CheckCircle2 :size="17"/>{{page.props.flash.success}}</div>
<section class="workout-admin-hero"><div><span>مرکز برنامه‌ریزی مربی</span><h2>تمرین هدفمند برای تیم و ورزشکار</h2><p>حرکت‌ها، حجم تمرین و بازه اجرا را مشخص کنید و انجام برنامه را دنبال کنید.</p></div><button class="primary-sport-button rounded-xl" @click="showForm=true"><Plus :size="17"/>ساخت برنامه جدید</button></section>
<section class="mt-4 grid gap-3 sm:grid-cols-3"><article class="access-stat rounded-xl"><div><span>کل برنامه‌ها</span><strong>{{plans.length}}</strong></div><Dumbbell :size="22"/></article><article class="access-stat rounded-xl"><div><span>برنامه فعال</span><strong>{{plans.filter(p=>p.status==='active').length}}</strong></div><Target :size="22"/></article><article class="access-stat rounded-xl"><div><span>حرکت تعریف‌شده</span><strong>{{plans.reduce((n,p)=>n+p.exercises.length,0)}}</strong></div><CheckCircle2 :size="22"/></article></section>
<section class="mt-4 space-y-3"><article v-for="plan in plans" :key="plan.id" class="workout-plan-card"><button class="workout-plan-head" @click="openPlan=openPlan===plan.id?null:plan.id"><span class="workout-plan-icon"><Dumbbell :size="21"/></span><div><span>{{plan.target_type==='team'?'برنامه تیمی':'برنامه اختصاصی'}} · {{plan.target}}</span><h3>{{plan.title}}</h3><p><CalendarDays :size="13"/>{{dateLabel(plan.starts_on)}} تا {{dateLabel(plan.ends_on)}} · مربی {{plan.coach}}</p></div><span class="workout-status" :class="`is-${plan.status}`">{{statusLabel(plan.status)}}</span><ChevronDown :size="19" :class="{'rotate-180':openPlan===plan.id}"/></button><div v-if="openPlan===plan.id" class="workout-plan-body"><p v-if="plan.description" class="workout-description">{{plan.description}}</p><div class="workout-exercise-list"><div v-for="(exercise,index) in plan.exercises" :key="exercise.id"><b>{{index+1}}</b><div><span>{{exercise.day_label||'برنامه اصلی'}} · {{categories[exercise.category as keyof typeof categories]}}</span><strong>{{exercise.title}}</strong><small>{{exercise.sets?`${exercise.sets} ست`:''}} {{exercise.reps?`× ${exercise.reps} تکرار`:''}} {{exercise.duration_minutes?`· ${exercise.duration_minutes} دقیقه`:''}} {{exercise.rest_seconds?`· ${exercise.rest_seconds} ثانیه استراحت`:''}}</small></div><em>{{exercise.completion_count}} انجام</em></div></div><footer><button v-if="plan.status==='draft'" class="small-action" @click="setStatus(plan,'active')">فعال‌سازی و ارسال</button><button v-if="plan.status==='active'" class="small-action" @click="setStatus(plan,'completed')">بستن برنامه</button></footer></div></article><div v-if="!plans.length" class="member-empty compact"><Dumbbell :size="30"/><h2>اولین برنامه را بسازید</h2><p>یک برنامه تیمی یا اختصاصی تعریف کنید تا در پنل ورزشکار نمایش داده شود.</p></div></section>
<div v-if="showForm" class="modal-shell" @click.self="showForm=false"><section class="modal-card sm:!max-w-4xl"><header class="modal-head"><div><p class="section-kicker">برنامه جدید</p><h2>طراحی تمرین</h2></div><button @click="showForm=false"><X :size="20"/></button></header><form class="space-y-5 p-5" @submit.prevent="submit"><div class="grid gap-4 sm:grid-cols-2"><label class="form-label">عنوان برنامه<input v-model="form.title" class="form-input" placeholder="مثلاً افزایش توان پرش"><small v-if="form.errors.title">{{form.errors.title}}</small></label><label class="form-label">نوع تخصیص<select v-model="form.target_type" class="form-input"><option value="team">کل تیم</option><option value="athlete">ورزشکار خاص</option></select></label><label v-if="form.target_type==='team'" class="form-label">تیم<select v-model="form.team_id" class="form-input"><option v-for="team in teams" :key="team.id" :value="team.id">{{team.name}}</option></select></label><label v-else class="form-label">ورزشکار<select v-model="form.athlete_id" class="form-input"><option :value="null">انتخاب ورزشکار</option><option v-for="athlete in athletes" :key="athlete.id" :value="athlete.id">{{athlete.name}}</option></select></label><label class="form-label">شروع<input v-model="form.starts_on" type="date" class="form-input"></label><label class="form-label">پایان<input v-model="form.ends_on" type="date" class="form-input"><small v-if="form.errors.ends_on">{{form.errors.ends_on}}</small></label></div><label class="form-label">هدف و توضیحات<textarea v-model="form.description" class="form-textarea" rows="2" placeholder="هدف این دوره و نکات کلی"></textarea></label><section><div class="mb-3 flex items-center justify-between"><div><p class="section-kicker">حرکت‌های برنامه</p><h3 class="mt-1 text-sm font-black">{{form.exercises.length}} حرکت</h3></div><button type="button" class="secondary-button rounded-lg" @click="addExercise"><Plus :size="15"/>افزودن حرکت</button></div><article v-for="(exercise,index) in form.exercises" :key="index" class="workout-form-row"><div class="workout-form-number">{{index+1}}</div><div class="grid flex-1 gap-3 sm:grid-cols-4"><label class="form-label sm:col-span-2">نام حرکت<input v-model="exercise.title" class="form-input" placeholder="پرش جفت روی باکس"></label><label class="form-label">دسته<select v-model="exercise.category" class="form-input"><option v-for="(label,key) in categories" :key="key" :value="key">{{label}}</option></select></label><label class="form-label">روز برنامه<input v-model="exercise.day_label" class="form-input" placeholder="روز اول"></label><label class="form-label">ست<input v-model="exercise.sets" type="number" class="form-input"></label><label class="form-label">تکرار<input v-model="exercise.reps" type="number" class="form-input"></label><label class="form-label">مدت (دقیقه)<input v-model="exercise.duration_minutes" type="number" class="form-input"></label><label class="form-label">استراحت (ثانیه)<input v-model="exercise.rest_seconds" type="number" class="form-input"></label><label class="form-label sm:col-span-4">نکته مربی<input v-model="exercise.notes" class="form-input" placeholder="نحوه اجرا یا نکته ایمنی"></label></div><button type="button" class="text-red-500" @click="removeExercise(index)"><Trash2 :size="17"/></button></article></section><div class="flex items-center justify-between border-t border-slate-200 pt-4"><label class="form-label">وضعیت<select v-model="form.status" class="form-input !mt-0"><option value="active">فعال و ارسال برای اعضا</option><option value="draft">ذخیره پیش‌نویس</option></select></label><button class="primary-sport-button rounded-xl" :disabled="form.processing"><Dumbbell :size="17"/>ذخیره برنامه تمرینی</button></div></form></section></div>
</AppLayout></template>
